#[tokio::test]
async fn srt_import_preserves_cues_supersedes_pending_inference_and_exposes_transcript() {
 let r=setup().await;edit(&r,section(0)).await;
 let before=state(&r).await;let defaults=job(&before)["defaults"].clone();
 edit(&r,json!({"type":"importSrt","sceneId":"main-scene","text":"\u{feff}1\r\n00:00:02,250 --> 00:00:04,750\r\nשלום <i>עולם</i>\r\n\r\n2\r\n00:01:01.000 --> 00:01:04.000\r\nSecond line\r\ncontinued","settings":{"wordsPerRow":3,"rows":1},"defaults":defaults})).await;
 let s=state(&r).await;assert_eq!(job(&s)["status"],"superseded");
 let imported=tracks(&s);assert_eq!(imported.len(),1);assert_eq!(imported[0]["elements"].as_array().unwrap().len(),2);
 assert_eq!(imported[0]["elements"][0]["startTime"],270000);assert_eq!(imported[0]["elements"][0]["duration"],300000);
 assert_eq!(imported[0]["captionSource"]["origin"],"srt");assert_eq!(imported[0]["captionSource"]["words"][0]["text"],"שלום");assert_eq!(imported[0]["captionSource"]["words"].as_array().unwrap().len(),5);
 call(&r,"history.undo",json!({})).await; // grouped transcription edits are undoable
}
